// Creating a Promise
const fetchUser = new Promise((resolve, reject) => {
  setTimeout(() => {
    const success = true;
    if (success) {
      resolve({ id: 1, name: 'John Doe' });
    } else {
      reject(new Error('Failed to fetch user'));
    }
  }, 1000);
});

